const oldIp = '85.155.127.7';
const newIp = '85.155.127.16';

// Mantenha true na primeira execução.
// Troque para false somente depois de conferir a pré-visualização.
const dryRun = true;

// Opcional: informe um domínio exato para limitar o teste.
// Deixe vazio para verificar todas as zonas ativas acessíveis pelo token.
const zoneNameFilter = '';

function isIPv4(value) {
  const parts = String(value).split('.');
  return parts.length === 4 && parts.every((part) => {
    if (!/^\d{1,3}$/.test(part)) return false;
    const number = Number(part);
    return number >= 0 && number <= 255 && String(number) === String(Number(part));
  });
}

let tokenConfigured = false;
try {
  tokenConfigured = Boolean(String($env.CLOUDFLARE_API_TOKEN || '').trim());
} catch {
  tokenConfigured = false;
}

if (!tokenConfigured) {
  throw new Error(
    'A variável CLOUDFLARE_API_TOKEN não foi configurada no servidor do n8n.'
  );
}

if (!isIPv4(oldIp) || !isIPv4(newIp)) {
  throw new Error('O IP antigo ou o novo IP não é um IPv4 válido.');
}

if (oldIp === newIp) {
  throw new Error('O IP antigo e o novo IP não podem ser iguais.');
}

return [{
  json: {
    old_ip: oldIp,
    new_ip: newIp,
    dry_run: dryRun,
    zone_name_filter: String(zoneNameFilter || '').trim().toLowerCase(),
    started_at: new Date().toISOString()
  }
}];

const config = $('Configuração Cloudflare').first().json;
const pages = $input.all();
const zones = [];

for (const item of pages) {
  const response = item.json || {};
  const body = response.body && typeof response.body === 'object'
    ? response.body
    : response;

  const statusCode = Number(response.statusCode || 200);
  if (statusCode < 200 || statusCode >= 300 || body.success !== true) {
    throw new Error(
      `Falha ao listar zonas da Cloudflare. HTTP ${statusCode}: ${JSON.stringify(body.errors || body)}`
    );
  }

  for (const zone of body.result || []) {
    const zoneName = String(zone.name || '').trim().toLowerCase();
    if (!zone.id || !zoneName) continue;

    if (config.zone_name_filter && zoneName !== config.zone_name_filter) {
      continue;
    }

    zones.push({
      json: {
        ...config,
        zone_id: zone.id,
        zone_name: zoneName,
        account_id: zone.account?.id || null,
        account_name: zone.account?.name || null
      }
    });
  }
}

if (!zones.length) {
  throw new Error(
    config.zone_name_filter
      ? `Nenhuma zona ativa foi encontrada para ${config.zone_name_filter}.`
      : 'Nenhuma zona ativa foi encontrada para o token informado.'
  );
}

return zones;

const responses = $input.all();
const zones = $('Separar zonas').all();
const records = [];
const listingErrors = [];

for (let index = 0; index < responses.length; index += 1) {
  const zone = zones[index]?.json || {};
  const response = responses[index]?.json || {};
  const body = response.body && typeof response.body === 'object'
    ? response.body
    : response;
  const statusCode = Number(response.statusCode || 200);

  if (statusCode < 200 || statusCode >= 300 || body.success !== true) {
    listingErrors.push({
      zone: zone.zone_name || zone.zone_id || `índice ${index}`,
      statusCode,
      errors: body.errors || body
    });
    continue;
  }

  for (const record of body.result || []) {
    const isExactTarget =
      record.type === 'A' &&
      String(record.content || '').trim() === String(zone.old_ip || '').trim();

    if (!isExactTarget) continue;

    records.push({
      json: {
        ...zone,
        record_found: true,
        record_id: record.id,
        record_name: record.name,
        record_type: record.type,
        old_ip: record.content,
        new_ip: zone.new_ip,
        ttl: record.ttl,
        proxied: Boolean(record.proxied),
        comment: record.comment ?? null,
        tags: Array.isArray(record.tags) ? record.tags : [],
        status: zone.dry_run ? 'aguardando_pre_visualizacao' : 'pronto_para_atualizar'
      }
    });
  }
}

if (listingErrors.length) {
  throw new Error(
    `A consulta de registros falhou em uma ou mais zonas. Nenhuma alteração foi iniciada: ${JSON.stringify(listingErrors)}`
  );
}

if (!records.length) {
  const config = $('Configuração Cloudflare').first().json;
  return [{
    json: {
      ...config,
      record_found: false,
      status: 'nenhum_registro_encontrado',
      zones_checked: zones.length,
      message: `Nenhum registro A com o IP ${config.old_ip} foi encontrado.`
    }
  }];
}

return records;

return $input.all().map((item) => ({
  json: {
    ...item.json,
    status: 'simulacao',
    success: true,
    message: `SIMULAÇÃO: ${item.json.record_name} seria alterado de ${item.json.old_ip} para ${item.json.new_ip}.`
  }
}));

const responses = $input.all();
const records = $('Preparar registros encontrados').all();

return responses.map((item, index) => {
  const record = records[index]?.json || {};
  const response = item.json || {};
  const body = response.body && typeof response.body === 'object'
    ? response.body
    : response;
  const statusCode = Number(response.statusCode || 200);
  const updatedContent = String(body.result?.content || '').trim();

  const success =
    statusCode >= 200 &&
    statusCode < 300 &&
    body.success === true &&
    updatedContent === String(record.new_ip || '').trim();

  return {
    json: {
      ...record,
      success,
      status: success ? 'atualizado' : 'erro_na_atualizacao',
      http_status: statusCode,
      cloudflare_errors: body.errors || [],
      updated_content: updatedContent || null,
      message: success
        ? `${record.record_name} foi alterado de ${record.old_ip} para ${record.new_ip}.`
        : `Não foi possível confirmar a atualização de ${record.record_name}.`
    }
  };
});
